"""Round-7 theory from the user's cheat-sheet comparison list: only topics not already covered by TH/TH3/TH4/TH5. Examples are read-only."""

def T(number, question, answer, tags, example, pattern='computed'):
    return dict(id='TH6-%03d' % number, question=question, answer=answer,
                tags=tags.split('|'), examples=[example] if example else [],
                pattern=pattern, mistakes=[])

THEORY6 = [
 T(1, 'Why does WHERE a OR b AND c need parentheses, and which operator does SQL evaluate first?',
   'SQL evaluates AND before OR, so a OR b AND c means a OR (b AND c), which is often not what was intended. Write (a OR b) AND c when the OR choice must apply together with the other condition. The unparenthesised form returns extra rows silently, with no error, so parenthesise every mixed AND/OR condition.',
   'and or|precedence|parentheses|where',
   "SELECT (SELECT COUNT(*) FROM orders WHERE `Payment Type` = 'Check' OR `Payment Type` = 'Cash' AND `Shipping Fee` > 0) AS no_parens, (SELECT COUNT(*) FROM orders WHERE (`Payment Type` = 'Check' OR `Payment Type` = 'Cash') AND `Shipping Fee` > 0) AS with_parens;",
   'select_filter'),
 T(2, 'WHERE versus CASE WHEN: when do you filter rows and when do you label or conditionally count them?',
   'WHERE removes rows that fail a condition, so they are absent from the result and from every aggregate. CASE WHEN keeps every row and only computes a value per row, which makes it the tool for categories, labels and conditional aggregates such as SUM(CASE WHEN ... THEN 1 ELSE 0 END). Use WHERE to restrict the data and CASE WHEN to split or label it; they are not interchangeable.',
   'where|case when|conditional aggregate|label',
   "SELECT COUNT(*) AS all_orders, SUM(CASE WHEN `Payment Type` IS NULL THEN 1 ELSE 0 END) AS unpaid, SUM(CASE WHEN `Payment Type` IS NOT NULL THEN 1 ELSE 0 END) AS paid FROM orders;",
   'cond_agg'),
 T(3, 'How do AVG(col), SUM(col)/COUNT(*) and AVG(DISTINCT col) differ when the column has NULLs and repeated values?',
   'AVG(col) divides the sum of non-NULL values by the count of non-NULL values. SUM(col)/COUNT(*) divides by every row, so NULL rows lower the result, while SUM(col)/COUNT(col) matches AVG. AVG(DISTINCT col) first collapses equal values, so repeated observations lose their weight. Use AVG(col) unless the question explicitly asks for the average of unique values.',
   'avg|avg distinct|sum count|null',
   "SELECT AVG(`Minimum Reorder Quantity`) AS avg_col, SUM(`Minimum Reorder Quantity`)/COUNT(*) AS sum_over_all_rows, SUM(`Minimum Reorder Quantity`)/COUNT(`Minimum Reorder Quantity`) AS sum_over_non_null, AVG(DISTINCT `Minimum Reorder Quantity`) AS avg_distinct FROM products;",
   'null_handling'),
 T(4, 'Why is SUM(price * quantity) correct and SUM(price) * SUM(quantity) wrong for sales value?',
   'SUM(price * quantity) multiplies within each row first and then adds the line values, which is the definition of total sales. SUM(price) * SUM(quantity) multiplies two column totals and mixes values from different lines, so it generally overstates or misstates the total. Always do the row-level arithmetic before the aggregate.',
   'sum|price quantity|row level|order details|sales value',
   "SELECT SUM(`Unit Price` * `Quantity`) AS correct_total, SUM(`Unit Price`) * SUM(`Quantity`) AS wrong_total FROM `order details`;",
   'computed'),
 T(5, 'ORDER BY ... LIMIT N versus a threshold subquery for top N: which returns exactly N rows and which keeps ties?',
   'ORDER BY `List Price` DESC, ID ASC LIMIT 10 returns exactly ten rows when at least ten exist; the unique ID deterministically breaks price ties. To include all products tied at the tenth row, compute RANK() OVER (ORDER BY `List Price` DESC), filter PriceRank <= 10 in an outer query, and order the output by `List Price` DESC, ID ASC; do not add ID inside RANK because that would break the price ties. A threshold subquery using the tenth row price (LIMIT 1 OFFSET 9) and `List Price` >= cutoff is equivalent when the cutoff exists and is non-NULL. Boundary ties can make the tie-inclusive report return more than ten rows, while LIMIT and RANK return all available rows when fewer than ten exist. DENSE_RANK() <= 10 instead selects the top ten distinct price levels, not ties at the tenth row.',
   'limit|order by|top n|ties|threshold subquery|tie breaker',
   "SELECT ID, `Product Name`, `List Price` FROM (SELECT ID, `Product Name`, `List Price`, RANK() OVER (ORDER BY `List Price` DESC) AS PriceRank FROM products) ranked WHERE PriceRank <= 10 ORDER BY `List Price` DESC, ID ASC;",
   'topn_rank'),
 T(6, 'MAX(col) versus ORDER BY col DESC LIMIT 1: which one gives the whole record, and which handles ties?',
   'MAX(col) returns only the highest non-NULL value, not the row it belongs to. ORDER BY col DESC LIMIT 1 returns one whole row, but when several rows share the maximum it returns just one of them. To return every record holding the maximum, filter with WHERE col = (SELECT MAX(col) ...).',
   'max|order by limit|ties|whole row|subquery',
   "SELECT ID, `Product Name`, `List Price` FROM products WHERE `List Price` = (SELECT MAX(`List Price`) FROM products);",
   'subquery'),
 T(7, 'In a self join, why use a.ID < b.ID instead of a.ID <> b.ID for pairs?',
   'a.ID <> b.ID removes pairs of a row with itself but returns both (A, B) and (B, A), so every pair appears twice. a.ID < b.ID keeps exactly one ordered representative of each unordered pair and also removes self pairs. Use < whenever the question asks for pairs, such as two customers in the same city.',
   'self join|pairs|less than|not equal|duplicate pairs',
   "SELECT (SELECT COUNT(*) FROM customers a JOIN customers b ON a.City = b.City AND a.ID <> b.ID) AS both_directions, (SELECT COUNT(*) FROM customers a JOIN customers b ON a.City = b.City AND a.ID < b.ID) AS unique_pairs;",
   'self_join'),
 T(8, 'UNION versus OR: when are they equivalent, and when does UNION change the result?',
   'For two conditions on the same table, WHERE a OR b is simpler and returns each qualifying row once. UNION runs two separate SELECT statements and removes duplicate result rows, so it is needed when the branches come from different tables or shapes. UNION also deduplicates identical output rows that come from different source rows, which OR never does. UNION ALL keeps duplicates and is cheaper when no duplicates can occur.',
   'union|or|deduplicate|union all',
   "SELECT (SELECT COUNT(*) FROM orders WHERE `Payment Type` = 'Check' OR `Shipping Fee` > 0) AS with_or, (SELECT COUNT(*) FROM (SELECT `Payment Type` AS p FROM orders WHERE `Payment Type` = 'Check' UNION SELECT `Payment Type` FROM orders WHERE `Shipping Fee` > 0) u) AS with_union;",
   'set_ops'),
 T(9, 'IN versus = with a subquery: what happens when the subquery returns several rows?',
   'IN accepts a subquery that returns any number of rows and tests membership. = expects a scalar subquery, and MySQL raises error 1242 (subquery returns more than 1 row) if it returns several. Use = only when exactly one value is guaranteed, such as a MAX or a primary-key lookup, and IN for multi-row sets.',
   'in|equals|scalar subquery|multi row|error 1242',
   "SELECT COUNT(*) FROM orders WHERE `Customer ID` IN (SELECT ID FROM customers WHERE City = 'Seattle');",
   'in_notin'),
 T(10, 'After a one-to-many JOIN, why do COUNT(*) and DISTINCT give misleading answers and what is the safe count?',
   'Joining customers to orders and order details repeats each order once per matching detail row, so COUNT(*) counts joined lines rather than orders. Keep the order details join, group by customer ID and names, and use COUNT(DISTINCT o.`Order ID`) AS TotalOrders so repeated lines cannot inflate the order count. In general count the distinct key of the entity requested: COUNT(DISTINCT c.ID) counts customers, not their orders. SELECT DISTINCT removes duplicate output rows after aggregation and cannot repair an inflated aggregate. If customers without orders or orders without details must remain, use LEFT JOIN for both joins; counting distinct non-NULL order IDs still reports zero for customers without orders.',
   'count distinct|join|one to many|duplicates|distinct',
   "SELECT c.ID, c.`First Name`, c.`Last Name`, COUNT(DISTINCT o.`Order ID`) AS TotalOrders FROM customers c LEFT JOIN orders o ON o.`Customer ID` = c.ID LEFT JOIN `order details` d ON d.`Order ID` = o.`Order ID` GROUP BY c.ID, c.`First Name`, c.`Last Name` ORDER BY c.ID;",
   'multi_agg'),
 T(11, 'CAST versus implicit conversion: why make a type conversion explicit, and what does CAST on a column cost?',
   'CAST(expr AS type) states the intended type, whereas implicit conversion depends on operand types and can silently compare text as numbers or produce warnings. Explicit casts make results like integer division or text-to-number comparison predictable. Wrapping an indexed column in CAST inside WHERE usually prevents an index lookup, so cast the constant instead when possible.',
   'cast|implicit conversion|type|index',
   "SELECT CAST('2006-04-15' AS DATE) AS d, CAST(7 AS DECIMAL(10,2)) / 2 AS dec_div, 7 DIV 2 AS int_div;",
   'computed'),
 T(12, 'Does GROUP BY guarantee sorted output, and what do ORDER BY inside OVER and the outer ORDER BY each control?',
   'GROUP BY forms groups and in MySQL 8.0 gives no ordering guarantee, so an explicit ORDER BY is required whenever order matters. ORDER BY inside OVER defines the sequence for the window calculation such as ROW_NUMBER or a running total. It does not fix the order of the displayed rows, so the outer ORDER BY is still needed for presentation.',
   'group by|order by|over|window|outer order by',
   "SELECT `Order ID`, `Shipping Fee`, ROW_NUMBER() OVER (ORDER BY `Shipping Fee` DESC, `Order ID`) AS rn FROM orders ORDER BY rn LIMIT 5;",
   'topn_rank'),
]
